/** One object renderer shared by the pickup stand and exposed mineral seams. */
export function drawWayglassProp(c,x,y,time,{seam=false,color='#b8ebd4'}={}){const X=x*48,Y=y*48;c.save();c.translate(X,Y);c.fillStyle='#0006';c.beginPath();c.ellipse(0,0,seam?24:20,8,0,0,Math.PI*2);c.fill();if(seam){c.fillStyle='#444b51';c.beginPath();c.moveTo(-24,1);c.lineTo(-19,-18);c.lineTo(0,-26);c.lineTo(21,-13);c.lineTo(27,2);c.closePath();c.fill();for(let i=0;i<3;i++){const px=(i-1)*13,py=-12-i%2*8;c.shadowColor=color;c.shadowBlur=10+3*Math.sin(time*2);const g=c.createLinearGradient(px-8,py-35,px+8,py);g.addColorStop(0,'#fff9d9');g.addColorStop(.35,color);g.addColorStop(1,'#245563');c.fillStyle=g;c.beginPath();c.moveTo(px,py-35);c.lineTo(px+8,py-17);c.lineTo(px+5,py);c.lineTo(px-6,py-1);c.lineTo(px-8,py-17);c.closePath();c.fill();c.shadowBlur=0;c.strokeStyle='#efffef88';c.beginPath();c.moveTo(px,py-35);c.lineTo(px,py-1);c.stroke();}}else{c.fillStyle='#1e3542';c.strokeStyle='#c3a36a';c.lineWidth=3;c.beginPath();c.ellipse(0,-5,20,8,0,0,Math.PI*2);c.fill();c.stroke();c.beginPath();c.ellipse(0,-31,19,24,-.3,0,Math.PI*2);c.stroke();c.lineWidth=1.5;c.beginPath();c.ellipse(0,-31,19,8,.35,0,Math.PI*2);c.stroke();c.shadowColor='#a4efd8';c.shadowBlur=14;c.fillStyle='#9de6d5';c.beginPath();c.moveTo(0,-48);c.lineTo(8,-31);c.lineTo(0,-14);c.lineTo(-7,-31);c.closePath();c.fill();c.shadowBlur=0;c.strokeStyle='#816548';c.lineWidth=4;c.beginPath();c.moveTo(-13,-6);c.bezierCurveTo(-40,-15,-35,-43,-16,-33);c.stroke();}c.restore();}
